    "notes": [
      "[Tr. 42] ……着呢: Đứng sau tính từ và một số động từ chỉ trạng thái tâm lý để chỉ mức độ, tương đương 很. Ví dụ: 时间还早着呢。 / 今天外边冷着呢。 / A：你的肚子疼吗？B：疼着呢。",
      "[Tr. 42] 都……了: Giữa 都 và 了 thường có từ chỉ thời gian hoặc cụm số lượng. 都 có nghĩa 已经 và không nhấn giọng, dùng để nhấn mạnh đã muộn, đã lớn tuổi hoặc số lượng đã nhiều. Ví dụ: 都七点五十五了，快走吧。 / 都二十岁了，自己的事情应该自己做了。",
      "[Tr. 42] 着什么急: 什么 trong câu hỏi tu từ có thể biểu thị sự không hài lòng hoặc không đồng tình. Ví dụ: 说什么？别说了，上课了。 / 着什么急？时间还早呢。 / 你笑什么？有什么可笑的？",
      "[Tr. 42–43] 该……了: Theo tình hình hoặc kinh nghiệm, đã đến lúc làm một việc. Ví dụ: 十二点了，该睡觉了。 / 时间到了，该出发了。",
      "[Tr. 43] 有什么好事啦: 啦 kết hợp 了 và 啊. Trong câu này 啦 biểu thị ngữ khí nghi vấn.",
      "[Tr. 43–44] Ngữ cảnh in kèm các ví dụ về 了: 秋天到了。／以前上大学，没工作。／原来不想跟我们一起去。／不能穿了。／又长高了。／结婚前还工作。／原来打算回国。／昨天还发烧。"
    ],
