        "explain": "来 và 去 đứng sau động từ để chỉ hướng của hành động. 来 hướng về phía người nói hoặc sự vật đang được nhắc đến. 去 chỉ hướng ngược lại. Tân ngữ chỉ nơi chốn đặt sau động từ và trước 来／去. Tân ngữ chỉ sự vật có thể đứng trước hoặc sau 来／去.",
