        "py": "Yǒu de kǔ, yǒu de bù kǔ. Wǒ hē de shì zhōngchéngyào, tiántián de, yìdiǎnr yě bù kǔ. Chī le zhèxiē zhōngyào wǒ de bìng jiù hǎo le.",
        "vi": "Có loại đắng, có loại không. Tôi uống thuốc đông y bào chế sẵn, ngọt ngọt, chẳng đắng chút nào. Uống mấy thứ thuốc ấy xong tôi khỏi bệnh.",
