    "workbook": {
      "exercisesNote": "Các bài luyện tập trong giáo trình ở trang in 80–87. Trang 86 có bài đọc luyện nói và từ bổ sung.\n\n1. Ngữ âm (tr. 80–81).\n（1）Phân biệt âm và thanh điệu:\njīnglì / jīnglǐ / gǎnmào / kàn bào\nzhù yuàn / chū yuàn / zhōngyī / zhòng yì\nfāngfǎ / fàn fǎ / zhā zhēn / cházhèng\nyǎnzòu / yuánqiú / gāngqín / gǎnqíng\n（2）Đọc thành tiếng:\n来过、去过、吃过、喝过\n好听、好看、好吃、好玩儿\n好极了、冷极了、热极了、好看极了\n第一次、第二天、第三年、第四节课\n来过中国、吃过馒头、学过汉语、打过篮球\n打过电话、喝过中国茶、听过中国歌、看过中国电影\n亲耳听过、亲眼看见过、亲口吃过、亲手做过\n来过一次中国、吃过一次北京烤鸭、得过一次感冒\n一次也没去过、一次也没看过、一遍也没读过\n\n2. Thay thế theo mẫu (tr. 81–82). Mỗi cặp ở dưới dùng để thay phần tương ứng trong mẫu.\n（1）A：你听过中国音乐吗？ B：听过。／没听过。\n吃／北京烤鸭；看／中国电影；练／气功；得／感冒；学／书法\n（2）A：你听过几次中国音乐？ B：我只听过一次。\n来／中国；吃／烤鸭；看／展览；喝／中药；得／感冒\n（3）A：你参观过这个展览没有？ B：没有。（我没参观过这个展览。）\n学／太极拳；去／香港；吃／饺子；看／中国电影；坐／飞机；扎／针\n（4）A：你以前来／去过中国吗？ B：没有，这是第一次。\n看／京剧；听／中文歌；练／太极拳；参加／唱歌比赛；当／翻译；吃／烤白薯\n\n3A. Từ cho sẵn ở trang 83: 治、烤鸭、感冒、极了、院、钢琴、菜、中药.\n\n3B. Chọn 次 hoặc 遍 điền vào chỗ trống (tr. 83).\n（1）我已经去过两____长城了。\n（2）那个展览我看过一____。\n（3）这本小说我看过一____。\n（4）今天的课文我已经读了八____了。\n（5）去年我爸爸来/去过一____北京。\n（6）老师，让我们再听一____录音，好吗？\n\n3C. Chọn 了 hoặc 过 điền vào chỗ trống (tr. 83–84).\n（1）我认识李老师，她给我们上____课。\n（2）这个语法我们还没有学____。\n（3）明天上午下____课我就去医院看她。\n（4）我去____他家，知道他住在哪儿。\n（5）我只看____中国电视，没看____中国电影。\n（6）他从香港给我带来____一件礼物。\n\n4. Luyện theo mẫu (tr. 84).\nMẫu:\nA：你去过美国吗？\nB：去过。\nA：你去过几次？\nB：去过一次。\nA：你去过韩国没有？\nB：一次也没去过。\n（1）去过一次韩国／没去过日本\n（2）去过两次意大利／没去过美国\n（3）去过三次北京／没去过广州\n（4）去过一次上海／没去过杭州\n\n5. Trả lời theo tình huống thực tế (tr. 84–85).\n（1）来中国以前你学过汉语没有？学过多长时间？\n（2）你以前来过中国没有？来过几次？\n（3）你以前看过中国电影没有？看过几次？看过什么电影？\n（4）你看过翻译的中国小说没有？看过什么小说？\n（5）来中国以后去过什么地方？你吃过哪些中国菜？\n（6）你去过哪些国家？\n（7）你来中国以前工作过没有？做过什么工作？\n（8）来中国以后你得过病没有？得过什么病？住过医院吗？\n（9）你听过中国音乐吗？学过中国歌没有？\n\n7. Đọc rồi luyện nói (tr. 86).\n今天上课，我们学习的语法是“动词＋过”，老师要大家用这个语法，互相问答。同学们问了很多问题，“你以前来过中国没有？”，“吃过中国菜没有？”，“看过中国电影没有？”等等。我问山本：“你谈过恋爱没有？”山本脸一红，说当然谈过。山本问我的问题是：“你说过谎没有？”我回答，当然说过。记得小时候，有一天我不想去上学了，就给老师打电话，说：“老师，我的小麦克病了，今天不能去上课了。”老师一听是我的声音，就问，你是谁呀？我说：“我是我爸爸。”\n山本又问马丁说过谎没有。马丁说：“没有。山本，我是世界上最老实的人，从来不说谎。也没有谈过恋爱，要是你的男朋友跟你分手了，你就做我的女朋友吧。”\n麦克听了大声地对山本说：“山本，你别听他的，马丁正在说谎，他谈过三次恋爱。”\n听了麦克的话，大家都笑了。马丁说：“听了麦克的话，你们就知道什么叫说谎了。”",
      "answerKeyNote": "Đáp án tham khảo cho mục 6 (trang in 162):\n1. 从九月开始，我开始在这个大学学汉语。\n2. 我每天都读一遍课文。\n3. 来中国以后，我没有看过病。\n4. 我朋友来中国了，上星期我去看过他。\n5. 我们见过一次面。\n6. 这个中国电影我在电视上看过。"
    },
