    "workbook": {
      "exercisesNote": "Các bài luyện tập trong giáo trình ở trang in 95–104. Trang 103 có bài đọc luyện nói và từ bổ sung.\n\n1. Ngữ âm (tr. 95–96).\n（1）Phân biệt âm và thanh điệu:\ndǎoyóu / dǎoliú / xūyào / xīyào\nlìyòng / lǐyóu / lǎobǎn / rǎoluàn\nyánjiū / yān jiǔ / zìyóu / jí yóu\n（2）Đọc thành tiếng:\n研究问题、研究语言、研究文化、认真研究\n高高兴兴、漂漂亮亮、马马虎虎、清清楚楚\n一听就懂、一看就会、一说就知道\n一感冒就发烧、一感冒就咳嗽、一喝咖啡就不能睡觉\n一下课就吃饭、一下课就回宿舍、一做完练习就看电视\n\n2. Thay thế theo mẫu (tr. 96–98).\n（1）\nA：你去北京了吗？ B：去了。\nA：你是什么时候去的北京？ B：我是上个星期去的。\n银行／前天；邮局／昨天；大使馆／上星期；王老师家／昨天晚上；医院／今天上午；公园／星期日\n（2）\nA：她是从哪儿来的？ B：她是从德国来的。\nA：她是一个人来的吗？ B：不是，她是跟旅游团一起来的。\n美国／朋友；日本／丈夫；香港／参观团；加拿大／公司经理；韩国／体育代表团；意大利／她爸爸\n（3）\nA：你们去博物馆了吗？ B：去了。\nA：你们是怎么去的？ B：我们是坐汽车去的。\n体育馆／骑车；展览馆／打的；花店／走路；西安／坐火车；法国／坐飞机\n（4）A：你是来留学的吗？ B：不是。我是来旅行的。\n旅行／参加比赛；买书／买光盘；参加比赛／看比赛；学习语言／学习中医；参观／照相；报名／考试\n（5）A：你的汉语是在哪儿学的？ B：在我们大学学的。（我的汉语是在我们大学学的。）\n这件毛衣／买／中国；这张光盘／买／书店；这件衣服／做／北京；研讨会／举行／台湾；电影节／举行／上海；晚会／举行／礼堂\n（6）一看就知道我是老外。\n听／知道他是南方人；听／喜欢这个歌；用／觉得不错；看／知道好不好；喝／知道是什么茶；摸／知道你有什么病\n\n3. Từ cho sẵn ở trang 99: 陪、组织、希望、风光、收集、互相、研究、老板、利用、需要.\n\n4. Luyện hội thoại theo mẫu (tr. 99–100).\nMẫu: 什么时候／哪儿／怎么／跟谁 → 前天／深圳／坐火车／旅游团\nA：丹尼丝是什么时候来的？ B：前天。\nA：她是从哪儿来的？ B：她是从深圳来的。\nA：她是怎么来的？ B：坐火车来的。\nA：她是一个人来的吗？ B：不是，她是跟旅游团一起来的。\n（1）玛丽／去年九月／英国／坐飞机／同学\n（2）小张／上个月／上海／坐火车／旅游团\n（3）你哥哥／早上／旅行社／坐出租车／老板\n（4）小王／上午／学校／骑自行车／朋友\n（5）秘书／八点／外贸公司／开车／经理\n\n5. Trả lời theo tình huống thực tế (tr. 100).\n（1）你是什么时候来中国的？\n（2）你是从哪国来的？\n（3）你以前来过中国吗？这是第几次？\n（4）你是怎么来的？\n（5）你是一个人来的吗？\n（6）来中国以前你工作过没有？\n（7）你学过什么外语？\n（8）你是在哪儿学的？\n\n6. Đóng vai nhà báo và phỏng vấn B (tr. 101).\nA：____！ B：你好！\nA：____？ B：昨天刚到的。\nA：____？ B：我是从英国来的。\nA：____？ B：不，我是和女儿一起来的。\nA：____？ B：我女儿在语言大学读书。\nA：____？ B：我来参加一个研讨会。\nA：____？ B：我觉得很好。\nA：____？ B：我已经来过中国很多次了，所以没有不习惯的问题。\nA：____。 B：不客气。\n\n7. Hoàn thành câu (tr. 101–102).\nVí dụ: 下午一到四点我就去操场锻炼身体。\n（1）我每天一起床就____。\n（2）她一到冬天就____。\n（3）她一感到寂寞就____。\n（4）他一喝酒脸____。\n（5）这种花一到夏天就____。\n（6）我一喝咖啡就____。\n（7）他一下课就____。\n（8）她一感冒就____。\n\n9. Đọc rồi luyện nói (tr. 103).\n我是前天到的北京，两年前曾经在中国学过两年汉语，是王老师的学生。这次我不是来学习的，是来旅行的。我不是一个人来的，是跟旅行团一起来的。我是旅行团的导游兼翻译。我现在还没有工作，在读研究生，研究的课题是《孔子与中国》，业余时间或寒暑假到一个旅行社去打工。这次，他们组织了一个旅游团，老板就让我陪团来了。他知道我需要经常来中国收集资料，所以，一有来中国的旅游团，就安排我陪团。我们先到香港，在香港玩了三天，又去了深圳，前天是从深圳坐火车过来的。原来打算坐飞机，但是旅行团的人都没有坐过中国的火车，很想坐坐中国的火车，看看铁路两边的风光。旅游团后天就回去了，我跟老板说好了，晚回去几天，等送他们上了飞机，我要到山东孔子的故乡去一趟。今天下午是自由活动时间，来看看王老师。",
      "answerKeyNote": "Đáp án tham khảo cho mục 8 (trang in 162):\n1. 你是什么时候来的中国？／你是什么时候来中国的？\n2. 我是在操场看见玛丽的。\n3. 他是今年九月来中国的。\n4. 我不是坐火车来中国的。\n5. 她是前天下午到的上海。\n6. 我汉字写得马马虎虎。\n7. 我们是坐汽车去博物馆参观的。\n8. 我是和朋友一起去的大使馆。"
    },
