      "answerKeyNote": "Sửa câu sai\n1. 昨天晚上，我工作到十点。\n2. 这张唱片我一听完就还给你。\n3. 老师的电话号码我忘了，因为我没记在本子上。\n4. 我下了飞机就看见了爸爸。 / 我一下飞机就看见了爸爸。\n5. 我打算在这儿学习到明年七月。\n6. 她进步很大，现在已经能听懂老师的话了。",
      "exercisesNote": "Luyện tập tr. 112–117. Mục 3A chọn từ tr. 114. Mục 3B phân biệt 过 và 了, 次 và 遍, tr. 114–115. Mục 4 và 5 điền bổ ngữ kết quả tr. 115–116. Mục 6 sửa câu sai tr. 116, đáp án tr. 163. Bài đọc luyện nói “丢了斧子以后” tr. 116–117. Tập viết tr. 117–118.\nTừ bổ sung của bài đọc (tr. 117) gồm 斧子 fǔzi (cái rìu), 邻居 línjū (hàng xóm), 偷 tōu (ăn trộm), 小偷 xiǎotōu (kẻ trộm), 表情 biǎoqíng (vẻ mặt), 言行 yánxíng (lời nói và hành động), 举动 jǔdòng (cử động), 砍柴 kǎnchái (đốn củi)."
