    "grammar": {
      "g10_1": {
        "title": "Diễn đạt sự tiếp diễn với động từ + 着",
        "explain": "Trợ từ 着 đứng sau động từ để miêu tả hành động đang diễn ra hoặc trạng thái tiếp tục duy trì sau một hành động. Ví dụ, 贴着 có thể tả thao tác dán đang diễn ra hoặc tình trạng vật đã được dán trên tường. Cấu trúc này cũng thường đi với 正在、正、在 và 呢.",
        "ex": "同学们走着，说着，笑着，可热闹啦。 / 他正在往墙上贴着红双喜字。 / 墙上贴着红双喜字。 / 她正在里面穿着衣服呢，请等一会儿。 / 她穿着一件红西服。 / 里边正上着课呢。 / 她来时，我正在躺着看书呢。"
      },
      "g10_2": {
        "title": "Phủ định và câu hỏi chính phản với 着",
        "explain": "Dạng phủ định là 没（有）+ động từ + 着, ít gặp trong giao tiếp. Dạng hỏi chính phản đặt 没有 sau động từ + 着.",
        "ex": "老师没在前面坐着，他站着呢。 / 教室的门没开着。 / 书上没写着名字，不知道是谁的书。 / 里边开着会没有？ / 墙上挂着地图没有？"
      },
      "g10_3": {
        "title": "Động từ + 着 trong câu liên động",
        "explain": "Trong câu có hai động từ, động từ thứ nhất mang 着 cho biết tư thế, trạng thái hoặc cách thức khi thực hiện hành động thứ hai.",
        "ex": "她正在前边站着讲话呢。 / 她笑着对我说：“欢迎！欢迎！” / 那里离这儿不远，我们走着去吧。"
      }
    },
